#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *owner = malloc(sizeof *owner);
    if (owner == NULL) {
        fputs("allocation failed\n", stderr);
        return 1;
    }

    *owner = 64;
    printf("value=%d\n", *owner);

    free(owner);
    owner = NULL;
    free(owner); /* safe: free(NULL) does nothing */
    puts("released");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

void destroy_int(int **owner) {
    if (owner == NULL) return;
    free(*owner);
    *owner = NULL;
}

int main(void) {
    int *number = malloc(sizeof *number);
    if (number == NULL) return 1;
    *number = 125;
    printf("before=%d\n", *number);

    destroy_int(&number);
    printf("owner_is_null=%s\n", number == NULL ? "yes" : "no");
    return 0;
}
